create extension if not exists pgcrypto;
create table if not exists contacts(id uuid primary key default gen_random_uuid(),name text not null,email text not null unique,phone text,business_name text,role text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists form_submissions(id uuid primary key default gen_random_uuid(),contact_id uuid references contacts(id) on delete set null,form_type text not null,source_page text,payload_json jsonb not null default '{}'::jsonb,status text not null default 'NEW',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists email_logs(id uuid primary key default gen_random_uuid(),contact_id uuid references contacts(id) on delete set null,submission_id uuid references form_submissions(id) on delete set null,email_type text not null,recipient_email text not null,provider text not null default 'RESEND',provider_message_id text,status text not null,error_message text,sent_at timestamptz,created_at timestamptz not null default now());
create table if not exists community_sessions(id uuid primary key default gen_random_uuid(),title text not null,slug text not null unique,summary text,starts_at timestamptz not null,timezone text not null default 'Australia/Brisbane',capacity integer,meeting_url text,status text not null default 'DRAFT',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists community_registrations(id uuid primary key default gen_random_uuid(),community_session_id uuid not null references community_sessions(id) on delete cascade,contact_id uuid not null references contacts(id) on delete cascade,status text not null default 'REGISTERED',marketing_consent boolean not null default false,registered_at timestamptz not null default now(),attended_at timestamptz,internal_notes text,unique(community_session_id,contact_id));
create table if not exists offers(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,path text not null,type text not null,short_description text,price_amount numeric,price_display text,status text not null default 'DRAFT',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists courses(id uuid primary key default gen_random_uuid(),offer_id uuid not null unique references offers(id) on delete cascade,session_count integer not null,max_students integer not null default 5,registration_status text not null default 'COMING_SOON',schedule_note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists cohorts(id uuid primary key default gen_random_uuid(),course_id uuid not null references courses(id) on delete cascade,name text not null,status text not null default 'FORMING',capacity integer not null default 5,internal_group_type text,internal_group_link text,internal_notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists enrolments(id uuid primary key default gen_random_uuid(),contact_id uuid not null references contacts(id) on delete cascade,course_id uuid not null references courses(id) on delete cascade,cohort_id uuid references cohorts(id) on delete set null,status text not null default 'NEW',payment_status text not null default 'PENDING',amount numeric,internal_notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(contact_id,course_id));
create table if not exists consent_records(id uuid primary key default gen_random_uuid(),contact_id uuid not null references contacts(id) on delete cascade,consent_type text not null,status text not null,scope_json jsonb not null default '{}'::jsonb,consent_text_version text not null,consent_text_snapshot text not null,source text not null,granted_at timestamptz,withdrawn_at timestamptz);
create table if not exists case_studies(id uuid primary key default gen_random_uuid(),type text not null,title text not null,slug text not null unique,challenge text,diagnosis text,approach text,outcome text,quote text,featured_image_url text,permission_status text not null default 'NOT_REQUESTED',status text not null default 'DRAFT',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
insert into offers(name,slug,path,type,short_description,price_amount,price_display,status) values('AI for Real Work','ai-for-real-work','LEARN','COURSE','Teach AI how to do one real job well.',150,'A$150','ACTIVE'),('AI for Business Builder','ai-for-business-builder','LEARN','COURSE','Design how AI fits across your business.',450,'A$450','ACTIVE'),('Initial 1:1 AI Business Session','initial-ai-business-session','SOLVE','CONSULTING','Two-hour practical diagnosis session.',190,'A$190 / 2 hours','ACTIVE'),('Ongoing 1:1 Consulting','ongoing-consulting','SOLVE','CONSULTING','Practical AI and business-system support.',150,'A$150 / hour','ACTIVE'),('Business-first Landing Pages','business-first-landing-pages','BUILD','SERVICE','Focused landing pages for small businesses.',null,'By enquiry','ACTIVE') on conflict(slug) do nothing;
insert into courses(offer_id,session_count,max_students,registration_status,schedule_note) select id,3,5,'OPEN','Session dates are arranged with each cohort.' from offers where slug='ai-for-real-work' on conflict(offer_id) do nothing;
insert into courses(offer_id,session_count,max_students,registration_status,schedule_note) select id,9,5,'OPEN','Session dates are arranged with each cohort.' from offers where slug='ai-for-business-builder' on conflict(offer_id) do nothing;